#!/usr/bin/env pwsh
# Generated by fmverify. Fetches the solver this layer's proofs are discharged by.
#
# Microsoft.Z3 is not on nuget.org (publishing stopped at 4.12.2 in 2023), so the package
# comes from the official Z3Prover release and lands in .packages/, which NuGet.config adds
# as a source. .packages/ is deliberately NOT committed — this script rebuilds it.
#
# The hash is not a formality. The solver decides whether a proof passes, so a package that
# does not match is refused rather than used.
$ErrorActionPreference = "Stop"

# Invoke-WebRequest's progress rendering makes a 65 MB download several times slower on
# Windows PowerShell.
$ProgressPreference = "SilentlyContinue"

# Deliberately not Get-FileHash: it ships in Microsoft.PowerShell.Utility, which is trimmed
# or blocked on some managed Windows installs, and this script must not fail there. The .NET
# APIs below are available whenever PowerShell runs in full language mode, and streaming
# avoids holding the whole package in memory.
function Get-Sha256Hex([string] $path) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $stream = [System.IO.File]::OpenRead($path)
    try { $bytes = $sha.ComputeHash($stream) }
    finally { $stream.Dispose(); $sha.Dispose() }
    return (($bytes | ForEach-Object { $_.ToString("x2") }) -join "")
}

Push-Location $PSScriptRoot
try {
    $version = "5.3.3"
    $sha256  = "3ece54cefce4d58be1ce7c00bcff34b691e8076169cba095a057284bfb0b7822".ToLowerInvariant()
    $url     = "https://github.com/Z3Prover/z3/releases/download/z3-5.3.3/Microsoft.Z3.5.3.3.nupkg"
    $packagesDir = Join-Path $PSScriptRoot ".packages"
    $nupkg       = Join-Path $packagesDir "Microsoft.Z3.$version.nupkg"

    if ((Test-Path $nupkg) -and ((Get-Sha256Hex $nupkg) -eq $sha256)) {
        Write-Host "Solver Microsoft.Z3 $version already present and verified."
        return
    }

    New-Item -ItemType Directory -Force $packagesDir | Out-Null
    Write-Host "Fetching Microsoft.Z3 $version from $url"
    Invoke-WebRequest -Uri $url -OutFile $nupkg

    $actual = Get-Sha256Hex $nupkg
    if ($actual -ne $sha256) {
        Remove-Item $nupkg -Force
        Write-Error "Solver package hash mismatch. Refusing to use it.`n  expected $sha256`n  actual   $actual"
    }

    Write-Host "Solver Microsoft.Z3 $version fetched and verified."
} finally { Pop-Location }
